# Detailed ASCII view of the answer with very sensitive threshold
crop = img.crop((180, 1716, 420, 1770))
arr = np.array(crop)

print("Answer region, threshold=100:")
for y in range(0, arr.shape[0], 1):
    line = ""
    for x in range(0, arr.shape[1], 1):
